package android.content; import java.util.*; public class SharedPreferences {final Map<String,Object> data=new HashMap<>(); public boolean contains(String key){return data.containsKey(key);} public String getString(String k,String d){return (String)data.getOrDefault(k,d);} public long getLong(String k,long d){return (Long)data.getOrDefault(k,d);} public boolean getBoolean(String k,boolean d){return (Boolean)data.getOrDefault(k,d);} public Map<String,?> getAll(){return new HashMap<>(data);} public Editor edit(){return new Editor();} public class Editor {Map<String,Object> changes=new HashMap<>();Set<String> removed=new HashSet<>();public Editor putString(String k,String v){changes.put(k,v);return this;}public Editor putBoolean(String k,boolean v){changes.put(k,v);return this;}public Editor putLong(String k,long v){changes.put(k,v);return this;}public Editor remove(String k){removed.add(k);return this;}public boolean commit(){removed.forEach(data::remove);data.putAll(changes);return true;}public void apply(){commit();}}}